<script setup lang="ts">
import {onUnmounted,ref} from 'vue';import {NButton,NCard,NTabPane,NTabs} from 'naive-ui';import {api,ApiError,errorMessage,type Workspace} from '../../shared/api';import PageHeader from '../../shared/ui/PageHeader.vue';import AsyncState from '../../shared/ui/AsyncState.vue';import StatusBadge from '../../shared/ui/StatusBadge.vue';import ChannelBrand from '../employees/ChannelBrand.vue';import DirectorySyncManagement from './DirectorySyncManagement.vue';
const props=defineProps<{workspace:Workspace}>(),emit=defineEmits<{open:[string];sessionExpired:[]}>();type Connection={id:string;entityId:string;employeeName:string;provider:'feishu'|'dingtalk'|'wecom';enabled:boolean;identity:string;directory:string;inboundVerified:boolean;transport:string};const rows=ref<Connection[]>([]),cursor=ref<string|null>(null),loading=ref(false),error=ref(''),tab=ref('connections');const c=new AbortController();async function load(more=false){loading.value=true;error.value='';try{const r=await api<{records:Connection[];nextCursor:string|null}>(`/workspaces/${encodeURIComponent(props.workspace.id)}/connections?limit=25${more&&cursor.value?'&cursor='+encodeURIComponent(cursor.value):''}`,c.signal);if(!c.signal.aborted){rows.value=more?[...rows.value,...r.records]:r.records;cursor.value=r.nextCursor;}}catch(e){if(!c.signal.aborted){error.value=errorMessage(e);if(e instanceof ApiError&&e.status===401)emit('sessionExpired');}}finally{loading.value=false;}}void load();onUnmounted(()=>c.abort());
</script><template><section><PageHeader :level="2" title="渠道连接"><NButton :disabled="loading" @click="load()">刷新连接</NButton></PageHeader><NTabs v-model:value="tab" type="line"><NTabPane name="connections" tab="渠道连接"><AsyncState :loading="loading&&!rows.length" :error="error" :empty="!loading&&!rows.length" @retry="load()"><div class="connections-grid"><NCard v-for="r in rows" :key="r.id"><template #header><ChannelBrand :provider="r.provider"/></template><h3>{{r.employeeName}}</h3><p>身份：<StatusBadge :status="r.identity"/></p><p>连接：尚未确认 · {{r.enabled?'配置已启用':'配置已停用'}}</p><p>目录：{{r.directory==='available'?'可查询':'不可用'}}</p><p>真实入站：{{r.inboundVerified?'已验证':'未验证'}}</p><NButton @click="emit('open',r.entityId)">查看连接详情</NButton></NCard></div><NButton v-if="cursor" :loading="loading" @click="load(true)">加载更多连接</NButton></AsyncState></NTabPane><NTabPane name="directory" tab="目录同步"><DirectorySyncManagement :workspace="workspace" @session-expired="emit('sessionExpired')"/></NTabPane></NTabs></section></template><style scoped>.connections-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(18rem,100%),1fr));gap:1.5rem;margin:1.5rem 0}</style>
